const msg = ($json && $json.message) || $('Telegram Trigger').first().json.message || {};
const trans = (($json && $json.transcripcion) || '').toString().trim();
const texto = String(trans || msg.text || '').trim();
const chatId = String((msg.chat && msg.chat.id) || '');
const nombre = (msg.from && msg.from.first_name) || 'Estimado cliente';
return [{ json: { chatId, texto, nombre } }];

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let t = '📋 Servicios Agente Veterinario\n\n';
try {
  const filas = ($('Leer Servicios').all() || []).map(i => i.json).filter(f => f && typeof f === 'object');
  for (const f of filas) {
    const nom = String(f.nombres || f.nombre || f.servicio || '').trim();
    const desc = String(f.descripcion || f['descripción'] || '').trim();
    if (nom) t += '• ' + esc(nom) + (desc ? ': ' + esc(desc) : '') + '\n';
  }
} catch (e) {}
t += '\nEscribe 0 para volver al menú.';
return [{ json: { textoFinal: t } }];

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let t = '❓ Preguntas frecuentes\n\n';
try {
  const filas = ($('Leer Faqs').all() || []).map(i => i.json).filter(f => f && typeof f === 'object');
  for (const f of filas) {
    const p = String(f.pregunta || '').trim();
    const r = String(f.respuesta || '').trim();
    if (p) t += esc(p) + '\n' + esc(r) + '\n\n';
  }
} catch (e) {}
t += 'Escribe 0 para volver al menú.';
return [{ json: { textoFinal: t } }];

const ev = $('Extraer Variables').first().json;
const chatId = String(ev.chatId || '');
const texto = String(ev.texto || '').trim();
const nombre = ev.nombre || '';
if (!chatId) return [{ json: { ok: false } }];
const ruta = String($json.ruta || '');
const store = $getWorkflowStaticData('global');
store.conv = store.conv || {};
let c = store.conv[chatId] || { chatId, nombre, firstMs: Date.now(), freeTexts: [], opciones: [] };
if (nombre) c.nombre = nombre;
c.opciones = c.opciones || []; c.freeTexts = c.freeTexts || [];
c.lastMs = Date.now();
if (!c.firstMs) c.firstMs = Date.now();
const tl = texto.toLowerCase();
const rutaLabel = { servicios: 'Servicios', faqs: 'FAQs', asesor: 'Asesor', agendar: 'Gestionar cita' };
const esNav = texto === '0' || tl === '/start' || tl === 'menu' || tl === 'inicio' || texto === '';
const esNumero = /^\d+$/.test(texto);
if (!esNav) {
  if (rutaLabel[ruta] && !c.opciones.includes(rutaLabel[ruta])) c.opciones.push(rutaLabel[ruta]);
  if (!esNumero) c.freeTexts.push(texto);
}
store.conv[chatId] = c;
return [{ json: { ok: true } }];

// Cierra conversaciones con mas de 15 min sin escribir y arma la fila para Registro.
const store = $getWorkflowStaticData('global');
store.conv = store.conv || {};
const GAP = 2 * 60 * 1000;
const now = Date.now();
const pad = n => String(n).padStart(2, '0');
function bogotaFrom(ms) {
  const b = new Date(ms - 5 * 3600000);
  const dia = b.getUTCFullYear() + '-' + pad(b.getUTCMonth()+1) + '-' + pad(b.getUTCDate());
  const hora = pad(b.getUTCHours()) + ':' + pad(b.getUTCMinutes());
  const ts = dia + ' ' + hora + ':' + pad(b.getUTCSeconds());
  const min = b.getUTCHours() * 60 + b.getUTCMinutes();
  const horario = (min >= 480 && min < 1260) ? 'Dentro de horario' : 'Fuera de horario';
  return { dia, hora, ts, horario };
}
const out = [];
for (const chatId of Object.keys(store.conv)) {
  const c = store.conv[chatId];
  if (c && c.lastMs && (now - c.lastMs) > GAP) {
    const bg = bogotaFrom(c.firstMs || c.lastMs);
    let mensaje = '';
    if (c.freeTexts && c.freeTexts.length) mensaje += c.freeTexts.join(' | ');
    if (c.opciones && c.opciones.length) mensaje += (mensaje ? ' — ' : '') + 'Consultó: ' + c.opciones.join(', ');
    if (!mensaje) mensaje = 'Interacción sin contenido';
    out.push({ json: {
      timestamp: bg.ts,
      horario: bg.horario,
      chatId,
      nombre: c.nombre || 'Sin nombre',
      mensaje,
      hora_bogota: bg.hora,
      dia: bg.dia,
      sede: 'Sin definir'
    } });
    delete store.conv[chatId];
  }
}
return out;

const msg = $('Telegram Trigger').first().json.message;
const transcripcion = (($input.first().json && $input.first().json.text) || '').toString().trim();
return [{ json: { message: msg, transcripcion } }];

const t = String($json.texto || '').toLowerCase().trim();
const has = s => t.includes(s);
const chatId = String($json.chatId || '');
const store = $getWorkflowStaticData('global');
const ret = (ruta) => [{ json: { texto: $json.texto, chatId: $json.chatId, nombre: $json.nombre, ruta } }];

if (t === '/start' || t === 'start' || t === '/menu' || t === 'menu' || t === 'menú' || t === 'inicio') {
  if (store.agendar) delete store.agendar[chatId];
  if (store.recordatorioPend) delete store.recordatorioPend[chatId];
  return ret('menu');
}
const segLista = (store.seguimiento && store.seguimiento.lista) || [];
if (chatId === '5050987637' && segLista.length && /^\d+\s+(si|sí|s|no|n)$/i.test(t)) return ret('seguimiento_resp');
if (store.encuesta && store.encuesta[chatId]) return ret('encuesta');
if (store.agendar && store.agendar[chatId]) return ret('agendar');
if (store.recordatorioPend && store.recordatorioPend[chatId]) return ret('confirmar_recordatorio');

// --- Blindaje (fuera de flujo) ---
const palabras = t.split(/[^a-záéíóúüñ0-9]+/i).filter(Boolean);
const groserias = new Set(['mierda','puta','puto','putas','putos','hijueputa','hpta','gonorrea','marica','maricon','maricón','malparido','malparida','imbecil','imbécil','idiota','idiotas','estupido','estúpido','estupida','estúpida','pendejo','pendeja','cabron','cabrón','verga','huevon','huevón','güevon','joder','jodido','carajo','coño','maldito','maldita','malnacido','tarado','baboso','inutil','inútil','ratero','ladron','ladrón','estafador','estafadores','basura','asco']);
if (palabras.some(w => groserias.has(w))) return ret('calma');

const digitos = t.replace(/[^0-9]/g, '');
if (digitos.length >= 12 || has('contraseña') || has('contrasena') || has('password') || has('cvv') || has('numero de tarjeta') || has('número de tarjeta')) return ret('seguridad');

let ruta = 'menu';
if (t === '1' || t === 'uno' || has('servicio')) ruta = 'servicios';
else if (t === '2' || t === 'dos' || has('pregunta') || has('horario') || has('faq') || has('frecuente') || has('duda')) ruta = 'faqs';
else if (t === '4' || t === 'cuatro' || has('asesor') || has('persona') || has('humano') || has('hablar con')) ruta = 'asesor';
else if (t === '3' || t === 'tres' || has('agendar') || has('agéndame') || has('agendame') || has('reservar') || has('reprogram') || has('cancelar') || has('anular') || has('gestionar') || has('mis citas') || has('quiero una cita') || has('quiero cita') || has('sacar cita') || has('sacar una cita') || has('pedir cita') || has('pedir una cita') || has('nueva cita') || has('una cita para') || has('un turno')) ruta = 'agendar';
else if (t === '0' || t === '' || /^(hola|holaa|holi|ola|buenas|buenos dias|buenos días|buenas tardes|buenas noches|hey|saludos|que tal|qué tal|buen dia|buen día)/.test(t)) ruta = 'menu';
else ruta = 'buscar';
return ret(ruta);

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
function toMin(s) {
  const m = String(s).trim().toUpperCase().match(/(\d{1,2}):(\d{2})\s*(AM|PM)?/);
  if (!m) return null;
  let h = parseInt(m[1], 10); const min = parseInt(m[2], 10); const ap = m[3];
  if (ap === 'PM' && h < 12) h += 12;
  if (ap === 'AM' && h === 12) h = 0;
  return h * 60 + min;
}
const cfg = (($('Leer Configuracion').all() || []).map(i => i.json).filter(f => f && f.horario))[0] || {};
const horario = String(cfg.horario || '8:00 AM - 9:00 PM');
const link = String(cfg.telegram || 'https://t.me/fimercadog_asesor');
const asesorChatId = String(cfg.id || '5050987637');
const duenoChatId = String(cfg['dueño'] || cfg['dueno'] || asesorChatId);
const partes = horario.split('-');
const ap = toMin(partes[0]); const ci = toMin(partes[1]);
const apertura = (ap == null) ? 480 : ap;
const cierre = (ci == null) ? 1260 : ci;
const aperturaTxt = (partes[0] || '8:00 AM').trim();
const b = new Date(Date.now() - 5 * 3600000);
const nowMin = b.getUTCHours() * 60 + b.getUTCMinutes();
const dentro = nowMin >= apertura && nowMin < cierre;
let falta = '';
if (!dentro) {
  let f = (nowMin < apertura) ? (apertura - nowMin) : ((1440 - nowMin) + apertura);
  const hh = Math.floor(f / 60); const mm = f % 60;
  if (hh && mm) falta = hh + (hh > 1 ? ' horas' : ' hora') + ' y ' + mm + ' minutos';
  else if (hh) falta = hh + (hh > 1 ? ' horas' : ' hora');
  else falta = mm + ' minutos';
}
const ev = $('Extraer Variables').first().json;
const nombre = ev.nombre || 'Cliente';
const chatId = ev.chatId;
const store = $getWorkflowStaticData('global');
const conv = (store.conv && store.conv[chatId]) || {};
const contexto = (conv.freeTexts && conv.freeTexts.length) ? conv.freeTexts.join(' | ') : (ev.texto || 'Pidió hablar con un asesor');
let textoFinal;
if (dentro) {
  textoFinal = 'Con gusto te conecto con un asesor de Agente Veterinario 👤\nEscribe o haz clic aquí: ' + link;
} else {
  textoFinal = 'Nuestro equipo humano está fuera de horario en este momento ⏰\nPuedes dejar tu mensaje aquí 👉 ' + link + '\n\nQuedas en cola y te responderán en aproximadamente ' + falta + ', mañana a partir de las ' + aperturaTxt + ' 🐾';
}
const avisoTexto = '🔔 Cliente solicita asesor — Agente Veterinario\n👤 Cliente: ' + esc(nombre) + '\n🆔 ChatID: ' + chatId + '\n💬 ' + esc(contexto);
return [{ json: { textoFinal, avisoTexto, asesorChatId, duenoChatId } }];

const ev = $('Extraer Variables').first().json;
const chatId = String(ev.chatId || '');
const texto = String(ev.texto || '').trim();
const tl = texto.toLowerCase();
const store = $getWorkflowStaticData('global');
store.agendar = store.agendar || {};
const cap = s => s ? (s.charAt(0).toUpperCase() + s.slice(1)) : s;
const pad = n => String(n).padStart(2, '0');

// especialidades activas
let esps = [];
try {
  esps = ($('Leer Especialidad').all() || []).map(i => i.json)
    .filter(f => f && String(f.estado || '').toLowerCase().includes('activ'))
    .map(f => cap(String(f.nombre || f.especialidad || '').trim()))
    .filter(Boolean);
} catch (e) {}
if (!esps.length) esps = ['General', 'Cirugía', 'Vacunación'];

const CAL = {
  '1': { sede: 'Sede 1', calId: '76224551305cf247fb1fac39416e191f3d89d01b7dee161bcbd902be1b1de0a1@group.calendar.google.com' },
  '2': { sede: 'Sede 2', calId: 'a8e971b77565b2856eee7cece902e672f359ef5eb3f30f84c02a721849960309@group.calendar.google.com' }
};
const DIAS = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
function bogNow() { return new Date(Date.now() - 5 * 3600000); }
function menuSede() { return '🏥 ¿En qué sede quieres tu cita?\n\n1. Sede 1\n2. Sede 2\n\nEscribe 1 o 2 (o 0 para salir).'; }
function menuEsp() { let m = '🩺 ¿Qué especialidad necesitas?\n\n'; esps.forEach((e, i) => { m += (i + 1) + '. ' + e + '\n'; }); m += '\nEscribe el número (si es algo general, elige General). 0 para salir.'; return m; }
function menuDias() {
  const OPEN = 8 * 60, CLOSE = 21 * 60, SLOT = 40;
  const b = bogNow();
  const nowMin = b.getUTCHours() * 60 + b.getUTCMinutes();
  const inicio = (Math.max(OPEN, nowMin + 30) <= CLOSE - SLOT) ? 0 : 1;
  const arr = []; let m = '📅 ¿Para qué día quieres la cita?\n\n';
  for (let k = 0; k < 7; k++) {
    const i = inicio + k;
    const x = new Date(b.getTime() + i * 86400000);
    const ymd = x.getUTCFullYear() + '-' + pad(x.getUTCMonth() + 1) + '-' + pad(x.getUTCDate());
    const et = (i === 0 ? 'Hoy' : (i === 1 ? 'Mañana' : DIAS[x.getUTCDay()])) + ' ' + pad(x.getUTCDate()) + '/' + pad(x.getUTCMonth() + 1);
    arr.push({ ymd, et }); m += (k + 1) + '. ' + et + '\n';
  }
  m += '\nEscribe el número del día (0 para salir).'; return { m, arr };
}
const R = (txt) => [{ json: { accion: 'responder', textoFinal: txt } }];

// salir
if (tl === '0' || tl === 'salir' || tl === 'menu') {
  delete store.agendar[chatId];
  return [{ json: { accion: 'menu' } }];
}

let st = store.agendar[chatId];
if (!st) {
  store.agendar[chatId] = { paso: 'submenu', datos: {} };
  if (/(reprogram|cambiar.*(cita|fecha|hora)|mover.*cita)/.test(tl)) return [{ json: { accion: 'reprog_listar' } }];
  if (/(cancelar|anular)/.test(tl)) return [{ json: { accion: 'cancel_listar' } }];
  if (/(ver.*cita|consultar|mis citas|tengo.*cita|cuales.*cita|cuáles.*cita)/.test(tl)) return [{ json: { accion: 'ver' } }];
  if (/(agendar|agéndame|agendame|reservar|sacar.*cita|pedir.*cita|nueva cita|quiero.*cita|una cita|un turno|programar)/.test(tl)) { store.agendar[chatId].paso = 'nombre'; return R('📝 Vamos a agendar tu cita.\n\n¿Cuál es tu nombre completo?'); }
  return R('📅 Gestionar mi cita\n\n1. Agendar una cita\n2. Consultar mis citas\n3. Reprogramar\n4. Cancelar\n\nEscribe el número (0 para salir).');
}
const datos = st.datos;

if (st.paso === 'submenu') {
  if (texto === '1') { st.paso = 'nombre'; return R('📝 Vamos a agendar tu cita.\n\n¿Cuál es tu nombre completo?'); }
  if (texto === '2') return [{ json: { accion: 'ver' } }];
  if (texto === '3') return [{ json: { accion: 'reprog_listar' } }];
  if (texto === '4') return [{ json: { accion: 'cancel_listar' } }];
  return R('📅 Gestionar mi cita\n\n1. Agendar una cita\n2. Consultar mis citas\n3. Reprogramar\n4. Cancelar\n\nEscribe el número (0 para salir).');
}
if (st.paso === 'nombre') {
  datos.nombre = texto;
  st.paso = 'mascota';
  return R('🐾 ¿Cómo se llama tu mascota? (si quieres dime también si es perro, gato, etc.)');
}
if (st.paso === 'mascota') {
  let especie = '';
  if (tl.indexOf('perr') >= 0 || tl.indexOf('canin') >= 0 || tl.indexOf('cachorr') >= 0) especie = 'Perro';
  else if (tl.indexOf('gat') >= 0 || tl.indexOf('felin') >= 0 || tl.indexOf('minin') >= 0) especie = 'Gato';
  else if (tl.indexOf('conej') >= 0) especie = 'Conejo';
  else if (tl.indexOf('ave') >= 0 || tl.indexOf('loro') >= 0 || tl.indexOf('pajar') >= 0 || tl.indexOf('pájar') >= 0) especie = 'Ave';
  else if (tl.indexOf('hamster') >= 0 || tl.indexOf('hámster') >= 0 || tl.indexOf('cuy') >= 0 || tl.indexOf('roedor') >= 0) especie = 'Roedor';
  const fillers = ['mi','el','la','los','las','un','una','se','llama','llamado','llamada','es','son','y','mascota','perro','perrito','perra','gato','gatito','gata','canino','felino','cachorro','minino','conejo','ave','loro','pajaro','pájaro','hamster','hámster','cuy','roedor'];
  let nom = texto.split(/\s+/).map(w => w.replace(/[.,]/g, '')).filter(w => w && fillers.indexOf(w.toLowerCase()) < 0).join(' ').trim();
  datos.mascota = nom || texto.trim();
  if (especie) { datos.especie = especie; st.paso = 'sede'; return R(menuSede()); }
  st.paso = 'especie';
  return R('¿Qué tipo de mascota es ' + datos.mascota + '? (perro, gato, u otro)');
}
if (st.paso === 'especie') {
  let especie = cap(texto.trim());
  if (tl.indexOf('perr') >= 0 || tl.indexOf('canin') >= 0) especie = 'Perro';
  else if (tl.indexOf('gat') >= 0 || tl.indexOf('felin') >= 0) especie = 'Gato';
  datos.especie = especie;
  st.paso = 'sede';
  return R(menuSede());
}
if (st.paso === 'sede') {
  const sel = CAL[texto];
  if (!sel) return R(menuSede());
  datos.sede = sel.sede; datos.calId = sel.calId;
  st.paso = 'especialidad'; st.esps = esps;
  return R(menuEsp());
}
if (st.paso === 'especialidad') {
  const lista = st.esps || esps;
  const i = parseInt(texto, 10);
  if (!i || i < 1 || i > lista.length) return R(menuEsp());
  datos.especialidad = lista[i - 1];
  st.paso = 'dia';
  const md = menuDias(); st.dias = md.arr;
  return R(md.m);
}
if (st.paso === 'dia') {
  const dias = st.dias || [];
  const i = parseInt(texto, 10);
  if (!i || i < 1 || i > dias.length) { const md = menuDias(); st.dias = md.arr; return R(md.m); }
  const dia = dias[i - 1];
  datos.fecha = dia.ymd; datos.fechaTxt = dia.et;
  st.paso = 'hora'; st.slotPage = 0;
  return [{ json: { accion: 'slots', calId: datos.calId, timeMin: dia.ymd + 'T00:00:00-05:00', timeMax: dia.ymd + 'T23:59:59-05:00', fecha: dia.ymd } }];
}
if (st.paso === 'reprog_elegir') {
  const lista = st.lista || [];
  const i = parseInt(texto, 10);
  if (!i || i < 1 || i > lista.length) return R('🔄 Escribe el número de una cita de la lista (0 para salir).');
  const c = lista[i - 1];
  datos.event_id = c.event_id; datos.calId = c.calId; datos.sede = c.sede;
  datos.mascota = c.mascota; datos.especie = c.especie; datos.especialidad = c.especialidad;
  st.paso = 'dia';
  const md = menuDias(); st.dias = md.arr;
  return R('🔄 Reprogramando: ' + c.mascota + ' — ' + c.especialidad + '\n\n' + md.m);
}
if (st.paso === 'cancel_elegir') {
  const lista = st.lista || [];
  const i = parseInt(texto, 10);
  if (!i || i < 1 || i > lista.length) return R('❌ Escribe el número de una cita de la lista (0 para salir).');
  const c = lista[i - 1];
  datos.event_id = c.event_id; datos.calId = c.calId; datos.sede = c.sede;
  datos.mascota = c.mascota; datos.especie = c.especie; datos.especialidad = c.especialidad;
  datos.fecha = c.fecha; datos.hora_cita = c.hora;
  st.paso = 'cancel_confirmar';
  return R('⚠️ ¿Seguro que quieres CANCELAR esta cita?\n\n🐾 ' + c.mascota + ' (' + c.especie + ')\n🩺 ' + c.especialidad + '\n📅 ' + c.fecha + ' a las ' + c.hora + '\n🏥 ' + c.sede + '\n\n1. Sí, cancelar\n0. No, volver al menú');
}
if (st.paso === 'cancel_confirmar') {
  if (texto === '1' || tl === 'si' || tl === 'sí' || tl === 'confirmar') {
    st.paso = 'cancelando';
    return [{ json: { accion: 'cancelar', calId: datos.calId, event_id: datos.event_id, mascota: datos.mascota, especie: datos.especie, especialidad: datos.especialidad, sede: datos.sede, hora_cita: datos.hora_cita, fecha_cita: datos.fecha, chatId } }];
  }
  return R('Para CANCELAR marca 1, o marca 0 para volver sin cancelar.');
}
if (st.paso === 'hora') {
  const slots = st.slots || [];
  const i = parseInt(texto, 10);
  const hayMas = st.slotsAll && (((st.slotPage || 0) + 1) * 8 < st.slotsAll.length);
  if (hayMas && i === slots.length + 1) { st.slotPage = (st.slotPage || 0) + 1; return [{ json: { accion: 'slots', calId: datos.calId, timeMin: datos.fecha + 'T00:00:00-05:00', timeMax: datos.fecha + 'T23:59:59-05:00', fecha: datos.fecha } }]; }
  if (!i || i < 1 || i > slots.length) {
    return [{ json: { accion: 'slots', calId: datos.calId, timeMin: datos.fecha + 'T00:00:00-05:00', timeMax: datos.fecha + 'T23:59:59-05:00', fecha: datos.fecha } }];
  }
  const s = slots[i - 1];
  if (new Date(s.startISO).getTime() <= Date.now() + 300000) { return [{ json: { accion: 'slots', calId: datos.calId, timeMin: datos.fecha + 'T00:00:00-05:00', timeMax: datos.fecha + 'T23:59:59-05:00', fecha: datos.fecha } }]; }
  datos.hora_cita = s.hora; datos.startISO = s.startISO; datos.endISO = s.endISO;
  if (st.modo === 'reprog') { st.paso = 'reprogramando'; return [{ json: { accion: 'reprogramar', calId: datos.calId, event_id: datos.event_id, startISO: datos.startISO, endISO: datos.endISO, mascota: datos.mascota, especie: datos.especie, especialidad: datos.especialidad, sede: datos.sede, hora_cita: datos.hora_cita, fecha_cita: datos.fecha, chatId } }]; }
  st.paso = 'observaciones';
  return R('✍️ Por último: ¿cuál es el motivo de la cita? Cuéntame por qué la necesitas (ej: vacunación, está decaído, control, una pata rota...).');
}
